import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new String(System.in.readAllBytes()).strip();
        int i = 0;
        while (i < s.length() && s.charAt(i) == '0') i++; // strip leading zeros
        // a power of two is a single 1 followed only by zeros
        boolean ok = i < s.length() && s.charAt(i) == '1' && s.indexOf('1', i + 1) < 0;
        System.out.println(ok ? "True" : "False");
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	data, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	t := strings.TrimLeft(strings.TrimSpace(string(data)), "0")
	// a power of two is a single 1 followed only by zeros
	if t != "" && t[0] == '1' && strings.Trim(t[1:], "0") == "" {
		fmt.Println("True")
	} else {
		fmt.Println("False")
	}
}
